#include "gnss_protocol.h"
#include <assert.h>
#include <stdio.h>
static unsigned packets;
static void received(void *ctx,const uint8_t *p,size_t n)
{
    (void)ctx;assert(gnss_meif_valid(p,n));packets++;
}
int main(void)
{
    /* Actual frame embedded in gpsd ELF at0x156313, not generated by this codec. */
    const uint8_t golden[]={0xa5,0x93,3,0,8,0,3,0,10,0,24,0,0xa5,0x68};
    struct gnss_meif_decoder d={0};
    for(size_t i=0;i<sizeof(golden);i++)gnss_meif_feed(&d,golden+i,1,received,NULL);
    assert(packets==1 && d.malformed==0);
    /* Actual live ACK from BCM4775 B1: no fourth header word. */
    const uint8_t ack[]={0xa5,0x93,0,0,6,0,1,3,10,0,0xa5,0x68};
    gnss_meif_feed(&d,ack,sizeof(ack),received,NULL);assert(packets==2);
    packets=1;
    uint8_t out[64];size_t n=gnss_meif_wrap(out,sizeof(out),golden+2,sizeof(golden)-4);
    assert(n==sizeof(golden) && !memcmp(out,golden,n));
    assert(!gnss_meif_wrap(out,4,golden+2,sizeof(golden)-4));
    uint8_t damaged[sizeof(golden)];memcpy(damaged,golden,sizeof(golden));damaged[8]^=1;
    gnss_meif_feed(&d,damaged,sizeof(damaged),received,NULL);assert(packets==1 && d.malformed==1);
    uint8_t packet[]={2,0x80,10,0,0xa5,0,1,0,0xa5,0,0,0};
    gnss_put16(packet+10,gnss_checksum(packet,10));
    n=gnss_meif_wrap(out,sizeof(out),packet,sizeof(packet));assert(n==18);
    gnss_meif_feed(&d,out,n,received,NULL);assert(packets==2);
    uint8_t too_big[GNSS_MEIF_MAX+2];memset(too_big,0,sizeof(too_big));
    gnss_meif_feed(&d,golden,2,received,NULL);gnss_meif_feed(&d,too_big,sizeof(too_big),received,NULL);
    gnss_meif_feed(&d,golden,sizeof(golden),received,NULL);assert(packets==3);
    uint8_t nav[32];assert(gnss_navigation_body(nav,sizeof(nav),golden,sizeof(golden))==16);
    assert(gnss_u16(nav)==14 && !memcmp(nav+2,golden,14));
    assert(!gnss_navigation_body(nav,4,golden,sizeof(golden)));
    puts("GNSS codec: stock frame, fragmented escape/checksum, corruption, overflow recovery and RPC boundary passed");return 0;
}
